parameters.jsCode:
const cfg = $('Config2').first().json;
const ideas = $json.output?.ideas;
if (!Array.isArray(ideas) || !ideas.length)
  return [{ json: { ok: false, error: 'no_ideas', ideas: [] } }];

const D = Number(cfg.duration_sec) || 30;
const valid = ideas.filter(i => {
  if (!Array.isArray(i.scenes) || i.scenes.length < 6 || i.scenes.length > 12) return false;
  const end = Math.max(...i.scenes.map(s => Number(s.t_end) || 0));
  return Math.abs(end - D) <= 2;
});
if (!valid.length)
  return [{ json: { ok: false, error: 'no_valid_' + D + 's_ideas', ideas: [] } }];

const out = valid.map(i => ({
  ...i,
  format: 'short',
  duration_sec: D,
  angle: i.angle || '',
  characters: i.characters || '',
  style_prompt: i.style_prompt || '',
  loop_ending: i.loop_ending || '',
  thumbnail_idea: i.thumbnail_idea || '',
  tags: Array.isArray(i.tags) ? i.tags : [],
  scenes_text: i.scenes
    .map(s => `[${s.t_start}-${s.t_end}s] ${s.visual} | CAM: ${s.camera || '-'} | SFX: ${s.sound || '-'}`)
    .join('\n'),
  status: Number(i.score) >= cfg.approve_score ? 'approved' : 'new'
}));
return [{ json: { ok: true, ideas: out } }];

const row = $input.first().json;
const SEGMENTS = 4;                    // Veo: first clip 8s + 7s per extension => 4 segments ~ 29s
const STARTS = [0, 8, 15, 22, 29];     // scene start-time buckets per segment

const scenes = [];
for (const line of String(row.scenes || '').split('\n')) {
  const m = line.trim().match(/^\[\s*([\d.]+)\s*-\s*([\d.]+)\s*s?\s*\]\s*(.*)$/i);
  if (!m) continue;
  const [visual, cam, sfx] = m[3].split(/\s*\|\s*(?:CAM|SFX):\s*/i);
  scenes.push({ start: Number(m[1]), visual: (visual || '').trim(), cam: (cam || '').trim(), sfx: (sfx || '').trim() });
}
if (!scenes.length) throw new Error('scenes column empty or unparsable for: ' + row.title);

const base = `${row.style_prompt || ''} Characters (identical in every shot): ${row.characters || ''}. Vertical 9:16, 24fps. No dialogue, no on-screen text, no subtitles.`.trim();

const segments = [];
for (let i = 0; i < SEGMENTS; i++) {
  const lo = STARTS[i];
  const hi = i === SEGMENTS - 1 ? Infinity : STARTS[i + 1];
  const b = scenes.filter(s => s.start >= lo && s.start < hi);
  const beats = b.map(s => s.cam && s.cam !== '-' ? `${s.visual} (${s.cam})` : s.visual).join(' Then ');
  const sfx = b.map(s => s.sfx).filter(x => x && x !== '-').join(', ');
  const parts = [];
  parts.push(i === 0 ? base : 'Continue the same scene seamlessly with the exact same characters, outfits, room and lighting. No dialogue, no text.');
  parts.push(`Action in order: ${beats || 'continue the story naturally'}.`);
  if (sfx) parts.push(`Sound: ${sfx}. Light playful music, no voice.`);
  if (i === SEGMENTS - 1 && row.loop_ending) parts.push(`Final shot: ${row.loop_ending}`);
  segments.push(parts.join(' '));
}

return [{ json: {
  ...row,
  segments,
  segTotal: SEGMENTS,
  seg: 1,
  prevTaskId: null,
  seed: Math.floor(10000 + Math.random() * 89999),
  urls: []
} }];

const req = $input.first().json;
if (req.code !== 200 || !req.data?.taskId)
  throw new Error('Veo request failed: ' + JSON.stringify(req).slice(0, 400));
const st = $('Segment Input').first().json;
return [{ json: { ...st, taskId: req.data.taskId } }];

const st = $('Carry State').last().json;
const url = $input.first().json.data?.response?.resultUrls?.[0];
if (!url) throw new Error('No resultUrls in Veo reply: ' + JSON.stringify($input.first().json).slice(0, 400));
const urls = [...(st.urls || []), url];
if (st.seg >= st.segTotal)
  return [{ json: { ...st, urls, videoUrl: url, finished: true } }];
return [{ json: { ...st, urls, seg: st.seg + 1, prevTaskId: st.taskId, finished: false } }];

